// use_figma script (read-only). Generated by `python3 scripts/figma-script.py tokens <mds-tag>` — do not edit by hand.
// Finds the library variables (by WEB code syntax) and text styles for the CSS a Magma component uses.
// A bare custom property name (`--magma-text-muted`) matches any code syntax that contains it.
/*__CONFIG__*/

const vars = await figma.variables.getLocalVariablesAsync();
const cols = await figma.variables.getLocalVariableCollectionsAsync();
const colName = (id) => (cols.find((c) => c.id === id) || {}).name;
const norm = (s) => s.replace(/\s+/g, '');
const out = {};
